SELECT DISTINCT s.symbol_id
FROM code.symbols s
JOIN code.calls c1 ON s.symbol_id = c1.caller_symbol_id
JOIN code.calls c2 ON s.symbol_id = c2.caller_symbol_id
WHERE c1.callee_symbol_id IN (
    SELECT symbol_id FROM code.symbols WHERE qualname = 'style' AND file_id IN (
      SELECT file_id FROM code.files WHERE module = 'termui'
    )
  )
  AND c2.callee_symbol_id IN (
    SELECT symbol_id FROM code.symbols WHERE qualname = 'echo' AND file_id IN (
      SELECT file_id FROM code.files WHERE module = 'utils'
    )
  )
  AND s.qualname LIKE '%click%';

